package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_panel_rating") public class PanelRating extends RspAuditedEntity{
 public enum Status{DRAFT,RETURNED,SUBMITTED,SUPERSEDED}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="stage_id",nullable=false,length=36)private String stageId;@Column(name="rater_employee_no",nullable=false,length=100)private String raterEmployeeNo;@Column(name="rating_revision",nullable=false)private int ratingRevision;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="current_rating_key",length=300)private String currentRatingKey;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="normalized_score",precision=12,scale=4)private BigDecimal normalizedScore;@Column(name="overall_remarks",length=2000)private String overallRemarks;@Column(name="submitted_at")private Instant submittedAt;@Column(name="returned_by",length=100)private String returnedBy;@Column(name="returned_at")private Instant returnedAt;@Column(name="return_reason",length=2000)private String returnReason;
 protected PanelRating(){}public PanelRating(String agency,String proceeding,String candidate,String stage,String rater,int revision,String prior){super(agency);proceedingId=requiredText(proceeding,"proceedingId");candidateId=requiredText(candidate,"candidateId");stageId=requiredText(stage,"stageId");raterEmployeeNo=requiredText(rater,"raterEmployeeNo");if(revision<1)throw new IllegalArgumentException("ratingRevision must be positive");ratingRevision=revision;supersedesId=optionalText(prior);currentRatingKey=proceedingId+":"+candidateId+":"+stageId+":"+raterEmployeeNo.toUpperCase(Locale.ROOT);status=Status.DRAFT;}
 public void calculate(BigDecimal score,String remarks){editable();if(score==null||score.signum()<0||score.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Rating score must be between 0 and 100");normalizedScore=score;overallRemarks=optionalText(remarks);}public void submit(String actor,Instant at){editable();if(!raterEmployeeNo.equalsIgnoreCase(requiredText(actor,"actor")))throw new IllegalLifecycleTransitionException("A panel member may submit only their own rating");if(normalizedScore==null)throw new IllegalLifecycleTransitionException("A complete rating is required");submittedAt=Objects.requireNonNull(at);returnedBy=null;returnedAt=null;returnReason=null;status=Status.SUBMITTED;}public void returnForCorrection(String actor,String reason,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only a SUBMITTED rating may be returned");if(raterEmployeeNo.equalsIgnoreCase(actor))throw new IllegalLifecycleTransitionException("A panel member cannot return their own rating");returnedBy=requiredText(actor,"actor");returnReason=requiredText(reason,"reason");returnedAt=Objects.requireNonNull(at);status=Status.RETURNED;}public void supersede(){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only a SUBMITTED rating may be superseded");currentRatingKey=null;status=Status.SUPERSEDED;}private void editable(){if(status!=Status.DRAFT&&status!=Status.RETURNED)throw new IllegalLifecycleTransitionException("Only a DRAFT or RETURNED rating may be edited");}
 public String getProceedingId(){return proceedingId;}public String getCandidateId(){return candidateId;}public String getStageId(){return stageId;}public String getRaterEmployeeNo(){return raterEmployeeNo;}public int getRatingRevision(){return ratingRevision;}public Status getStatus(){return status;}public BigDecimal getNormalizedScore(){return normalizedScore;}public String getOverallRemarks(){return overallRemarks;}public String getReturnReason(){return returnReason;}
}
